import{_ as e,o as t,c as o,a3 as s}from"./chunks/framework.BUxR7uXn.js";const u=JSON.parse('{"title":"Cocos粒子杂项暂存","description":"","frontmatter":{},"headers":[],"relativePath":"图形学/cocos粒子杂项暂存.md","filePath":"图形学/cocos粒子杂项暂存.md","lastUpdated":null}'),d={name:"图形学/cocos粒子杂项暂存.md"};function n(c,a,i,r,l,p){return t(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="cocos粒子杂项暂存" tabindex="-1">Cocos粒子杂项暂存 <a class="header-anchor" href="#cocos粒子杂项暂存" aria-label="Permalink to &quot;Cocos粒子杂项暂存&quot;">​</a></h1><h2 id="_2d粒子类型分类" tabindex="-1">2D粒子类型分类 <a class="header-anchor" href="#_2d粒子类型分类" aria-label="Permalink to &quot;2D粒子类型分类&quot;">​</a></h2><p>cocos2d 粒子主要可以按两个正交的维度分类：运动状态 x 位置</p><h3 id="运动状态" tabindex="-1">运动状态 <a class="header-anchor" href="#运动状态" aria-label="Permalink to &quot;运动状态&quot;">​</a></h3><p>按照运动状态可以分为 GRAVITY 和 RADIUS</p><h4 id="gravity-笛卡尔速度-牛顿积分" tabindex="-1">GRAVITY：笛卡尔速度 + 牛顿积分 <a class="header-anchor" href="#gravity-笛卡尔速度-牛顿积分" aria-label="Permalink to &quot;GRAVITY：笛卡尔速度 + 牛顿积分&quot;">​</a></h4><p>速度存在 <code>dir</code> 里。每帧先累加速度，再积分位置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>radialDir     = normalize(pos)                 // 相对发射源；在原点则为 0</span></span>
<span class="line"><span>tangentialDir = (-radialDir.y, radialDir.x)    // 逆时针 90°</span></span>
<span class="line"><span>vel += (gravity + radialDir * radialAccel + tangentialDir * tangentialAccel) * dt</span></span>
<span class="line"><span>pos += vel * dt * yCoordFlipped</span></span></code></pre></div><h5 id="三个加速度-两套坐标系" tabindex="-1">三个加速度：两套坐标系 <a class="header-anchor" href="#三个加速度-两套坐标系" aria-label="Permalink to &quot;三个加速度：两套坐标系&quot;">​</a></h5><ul><li><code>gravity</code>：世界轴上的常向量，<strong>所有粒子同一方向</strong>（通常往下）。不依赖粒子在哪，一个数就够。</li><li><code>radialAccel</code> / <code>tangentialAccel</code>：围着<strong>发射源</strong>的极坐标分解。方向依赖粒子位置，不能写成固定向量。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        tangential (-ry, rx) 逆时针</span></span>
<span class="line"><span>              ↑</span></span>
<span class="line"><span>              |</span></span>
<span class="line"><span>    发射源 ·--+--&gt; radial (rx, ry) 沿「源→粒子」</span></span>
<span class="line"><span>              |</span></span>
<span class="line"><span>              某粒子</span></span></code></pre></div><h5 id="为什么是两个参数" tabindex="-1">为什么是两个参数 <a class="header-anchor" href="#为什么是两个参数" aria-label="Permalink to &quot;为什么是两个参数&quot;">​</a></h5><p>相对发射源，任意力都能拆成「沿半径」和「垂直半径」两个分量——这是 2D 力场的两个自由度，也是给美术的两个旋钮：</p><ul><li>径向：改<strong>离发射源的远近</strong>。正的往外推（爆炸），负的往里拉（Galaxy 收束）。</li><li>切向：改<strong>绕发射源的角度</strong>，不直接改距离。有它才会转（Spiral）。</li></ul><p>只留 <code>gravity</code>，所有粒子永远被推向同一方向，做不出「绕着喷口转」或「被吸回中心」；只留径向，只能胀缩，转不起来。三者叠起来，才覆盖烟 / 烟花 / 星系 / 螺旋。</p><p>两个标量对所有粒子共用，方向却每帧随粒子当前位置重算——飞到哪里，力就指向「源→粒子」或垂直于它。出生时写死一个 <code>(ax, ay)</code> 做不到：飞走之后那个向量还指着旧方向，中心吸、螺旋都会散掉。</p><h5 id="实例与对比" tabindex="-1">实例与对比 <a class="header-anchor" href="#实例与对比" aria-label="Permalink to &quot;实例与对比&quot;">​</a></h5><p>引擎里的现成例子就是按这两个旋钮配的：<code>ParticleGalaxy</code> 径向 <code>-80</code> + 切向 <code>80</code>（往里收同时转）；<code>ParticleFlower</code> <code>-60</code> / <code>15</code>；<code>ParticleSpiral</code> <code>-380</code> / <code>45</code>（强吸、慢转，收成螺旋）。Fire / Smoke / Fireworks 两个都是 0，只靠出生 <code>speed</code> 和 <code>gravity</code>。</p><p>和 RADIUS 模式的差别：这里粒子仍有速度、有惯性，力只是在推它；RADIUS 每帧用 <code>(r, θ)</code> 重写位置，没有「飞过去被吸弯」这种惯性。GRAVITY 模式用两个标量换来的，是中心力场 + 牛顿积分可以叠在一起（星系还能再往下掉）。</p><h4 id="radius-极坐标-直接重算位置" tabindex="-1">RADIUS：极坐标 + 直接重算位置 <a class="header-anchor" href="#radius-极坐标-直接重算位置" aria-label="Permalink to &quot;RADIUS：极坐标 + 直接重算位置&quot;">​</a></h4><p>每颗粒子带着：</p><ul><li><code>angle</code>：弧度</li><li><code>degreesPerSecond</code>：角速度（名字是度，<strong>存的是弧度/秒</strong>）</li><li><code>radius</code> / <code>deltaRadius</code>：当前半径、每秒半径变化</li></ul><p>每帧不积速度，直接重算位置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>angle  += ω * dt</span></span>
<span class="line"><span>radius += deltaRadius * dt</span></span>
<span class="line"><span>pos = (-cos(angle) * radius, -sin(angle) * radius * yCoordFlipped)</span></span></code></pre></div><p>负号是 Particle Designer 约定。轨迹只能是「绕发射源的圆/螺线」：半径不变就是转圈，半径收到 0 就是往里卷。没有重力、没有切向这两个独立力。</p><p>两种状态<strong>不能混在一颗粒子上</strong>。SoA 里 <code>modeA</code> 和 <code>modeB</code> 数组都分配了，但 <code>update</code> 只进一个分支。要烟花往下掉用 GRAVITY；要法阵绕点转用 RADIUS。</p><h3 id="位置-已出生粒子钉在哪" tabindex="-1">位置：已出生粒子钉在哪 <a class="header-anchor" href="#位置-已出生粒子钉在哪" aria-label="Permalink to &quot;位置：已出生粒子钉在哪&quot;">​</a></h3><p>模拟始终在发射源局部。位置类型回答的是另一件事：喷出来之后，发射器（或别人）跑了，<strong>已经活着的粒子跟不跟</strong>。</p><p>粒子自己该飞还是飞，只是「家」订在哪不同：FREE 订在世界上出生的那个点，后面三种订在某个节点上。</p><p>出生时记下 <code>startPos</code>（参考点），画的时候再取一次「当前参考点」，用两者的差去折 <code>pos</code>。GROUPED 记下了也不用。</p><table tabindex="0"><thead><tr><th>类型</th><th>出生 startPos</th><th>发射器平移</th><th>发射器旋转/缩放</th><th>典型用法</th></tr></thead><tbody><tr><td>FREE</td><td>当时的世界坐标</td><td>不管</td><td>不跟（补偿掉了）</td><td>拖尾、爆炸碎屑留在原地</td></tr><tr><td>RELATIVE</td><td>节点 <code>_position</code></td><td>跟着</td><td>不跟旋转</td><td>挂在精灵上，要平移不要拧</td></tr><tr><td>TRACK</td><td>Track 节点局部</td><td>跟 Track</td><td>不跟旋转</td><td>系统挂在 A，却跟着父节点 B</td></tr><tr><td>GROUPED</td><td>写了不用</td><td>跟着</td><td><strong>完整跟着</strong></td><td>绑在角色/武器上一起转</td></tr></tbody></table><h4 id="free-不跟" tabindex="-1">FREE：不跟 <a class="header-anchor" href="#free-不跟" aria-label="Permalink to &quot;FREE：不跟&quot;">​</a></h4><p>烟已经喷到路上了，人走开，烟还留在原地继续飘。适合拖尾、爆炸碎屑。</p><p>发射器从世界点 W0 走到 W1。某粒子出生时 <code>startPos = W0</code>，局部 <code>pos</code> 是相对发射源的位移。画的时候把 W1 和 W0 都变到节点空间，差就是发射器这段时间的位移，从 <code>pos</code> 里减掉，粒子留在出生时的世界点附近（再加上它自己飞过的 <code>pos</code> 变化）。所以烟的尾巴留在走过的路上。</p><p>加速度<strong>不看</strong> FREE。径向 / 切向每帧仍是 <code>normalize(局部 pos)</code>，力心永远是模拟原点 <code>(0,0)</code>，也就是发射器当前的局部原点。FREE 只改画：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>画面世界位置 ≈ 出生时发射器世界点 W0 + 局部 pos</span></span></code></pre></div><p>局部 pos 被吸向 0，画面上就是被吸向 <strong>W0</strong>（这颗粒子出生时喷口在哪），不是现在的 W1。各颗的 <code>startPos</code> 不同，看起来就像每颗自带一口「出生时钉住的井」。<code>gravity</code> 同样在局部轴上加，FREE 也不改它的算法。Fire / Smoke 径向切向常为 0，发射器走开只剩初速和重力，这个错位看不出来。GROUPED 没有这层折算，吸向 0 就是吸向现在的喷口。</p><h4 id="relative-跟平移-不跟旋转" tabindex="-1">RELATIVE：跟平移，不跟旋转 <a class="header-anchor" href="#relative-跟平移-不跟旋转" aria-label="Permalink to &quot;RELATIVE：跟平移，不跟旋转&quot;">​</a></h4><p>喷口绑在角色身上，角色跑，烟团一起跑；角色转身，烟的形状不跟着拧。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>newPos = pos - (currentRef - startPos)</span></span></code></pre></div><p><code>currentRef - startPos</code> 是参考点这一帧相对出生时的平移。减掉它，等于让局部 <code>pos</code> 跟着参考点平移。旋转、缩放不在这个减法里，所以发射器转了，粒子云的形状不跟着拧，只是整体挪地方。</p><p>头文件注释把 RELATIVE 说成 “attached to the world but follow emitter repositioning”，GROUPED 说成 “attached to the emitter”。差别是：RELATIVE 只补偿平移；GROUPED 把 <code>pos</code> 当节点局部坐标，Node 的 model-view 整套吃进去。</p><h4 id="track-跟平移-但参考另一个节点" tabindex="-1">TRACK：跟平移，但参考另一个节点 <a class="header-anchor" href="#track-跟平移-但参考另一个节点" aria-label="Permalink to &quot;TRACK：跟平移，但参考另一个节点&quot;">​</a></h4><p>和 RELATIVE 一样只跟平移，但跟的不是发射器自己，是你指定的另一个节点。</p><p><code>currentRef</code> 换成 Track 节点：粒子系统可以是角色的子节点（吃层级），运动跟随却绑在另一个节点上。<code>_trackNode == null</code> 时 TRACK 退化成 RELATIVE。</p><h4 id="grouped-平移、旋转、缩放全跟" tabindex="-1">GROUPED：平移、旋转、缩放全跟 <a class="header-anchor" href="#grouped-平移、旋转、缩放全跟" aria-label="Permalink to &quot;GROUPED：平移、旋转、缩放全跟&quot;">​</a></h4><p>死死粘在身上。跑也跟、转也跟、缩放也跟。Studio 里默认基本是这种。</p><p><code>newPos = pos</code>，不做补偿。<code>draw</code> 时 Renderer 再乘节点 MV，平移旋转缩放全部作用在每个顶点上。角色转身 90°，整团粒子一起转。这就是「附着在发射器上」。</p><h4 id="补充" tabindex="-1">补充 <a class="header-anchor" href="#补充" aria-label="Permalink to &quot;补充&quot;">​</a></h4><p>同一套 GRAVITY 烟，FREE 是走过留下一串，GROUPED 是烟团粘在角色脚上。同一套 RADIUS 转圈，FREE 是圈子钉在出生点的世界位置，GROUPED 是圈子跟着节点走、跟着转。</p><p>Studio 不读 plist 的 positionType。节点名含 <code>_free</code> 才是 FREE，否则 <strong>GROUPED</strong>。游戏里大多数 CSB 粒子其实是 GROUPED，不是引擎默认的 FREE。</p><p>位置类型<strong>不改变</strong> <code>pos</code> 的积分，所以切 PositionType 不必重算运动；但必须在出生时就定好，因为 <code>startPos</code> 的空间（世界 / 节点 / Track）已经写进粒子里。中途改类型，旧粒子的 <code>startPos</code> 和新折法会对不上。</p>`,52)])])}const g=e(d,[["render",n]]);export{u as __pageData,g as default};
